import { env } from "cloudflare:workers";
import type { D1Migration } from "@cloudflare/vitest-pool-workers";
import { describe, expect, it } from "vitest";
import { applyAll, applyUpTo, foreignKeyViolations, one, seedLegacyWorld, snapshot } from "./world";

// 0051 (14 new v3 tables; 0053 adds three more for Discord, generated by drizzle-kit and made idempotent) and 0052 (three nullable users columns), applied on top of a populated production-like database.
const T = 1_800_000_000;
const run = (sql: string, ...b: unknown[]) => env.DB.prepare(sql).bind(...b).run();

describe("0051 and 0052 on a populated database", () => {
  it("is additive: no legacy row or column changes, new tables exist, existing accounts are not blocked", async () => {
    await applyUpTo(51);
    await seedLegacyWorld();
    const before = await snapshot();
    const usersBefore = (await env.DB.prepare("SELECT id, email, name, status FROM users ORDER BY id").all()).results;
    const colsBefore = (await env.DB.prepare("PRAGMA table_info(events)").all()).results;
    const tablesBefore = (await env.DB.prepare("SELECT name FROM sqlite_master WHERE type = 'table'").all<{ name: string }>()).results.map((r) => r.name);

    await applyAll();

    expect(await snapshot()).toEqual(before);
    expect((await env.DB.prepare("SELECT id, email, name, status FROM users ORDER BY id").all()).results).toEqual(usersBefore);
    expect((await env.DB.prepare("PRAGMA table_info(events)").all()).results).toEqual(colsBefore);
    const added = (await env.DB.prepare("SELECT name FROM sqlite_master WHERE type = 'table'").all<{ name: string }>()).results.map((r) => r.name).filter((n) => !tablesBefore.includes(n)).sort();
    expect(added).toEqual([
      "discord_guilds", "discord_link_codes", "discord_outbox", "dispute_events", "dispute_evidence", "dispute_evidence_blobs", "disputes", "feedback_attachment_blobs", "feedback_attachments", "feedback_reports", "lft_applications", "lft_listings", "lft_reports",
      "player_games", "player_profiles", "tournaments", "v3_discord_settings", "v3_registration_discord", "v3_result_corrections", "v3_team_captains",
    ]);
    // the three new users columns are nullable and empty for every existing account
    expect(await one("SELECT COUNT(*) FROM users WHERE adult_confirmed_at IS NOT NULL OR resume_consent_at IS NOT NULL OR discord_user_id IS NOT NULL")).toBe(0);
    expect(await foreignKeyViolations()).toEqual([]);
    // no money, date-of-birth or id-document column anywhere in the new tables
    for (const t of added) {
      const cols = (await env.DB.prepare(`PRAGMA table_info(${t})`).all<{ name: string }>()).results.map((c) => c.name);
      for (const c of cols) expect(c, `${t}.${c}`).not.toMatch(/dob|birth|aadhaar|aadhar|price|fee|amount|prize|payout|wallet|currency|email/i);
    }
  });

  it("re-running 0051 changes nothing (idempotent); 0052 is the only non-idempotent file and is listed as such", async () => {
    const m = (env.TEST_MIGRATIONS as D1Migration[]).find((x) => x.name.startsWith("0051"))!;
    expect(m.queries.length).toBeGreaterThan(30);
    for (const q of m.queries) await env.DB.prepare(q).run();
    expect(await one("SELECT COUNT(*) FROM sqlite_master WHERE name = 'trg_dispute_events_append_only'")).toBe(1);
    const n = (env.TEST_MIGRATIONS as D1Migration[]).find((x) => x.name.startsWith("0052"))!;
    expect(n.queries.every((q) => /^ALTER TABLE users ADD COLUMN (adult_confirmed_at|resume_consent_at|discord_user_id) /.test(q.trim()))).toBe(true);
  });

  it("the database refuses invalid rows (CHECKs), duplicates (unique indexes) and orphans (foreign keys)", async () => {
    const uid = "u-alice";
    await run("INSERT INTO tournaments (id, event_id, slug, title, game, format) VALUES ('t1', 'e1', 'cup-one', 'Cup One', 'bgmi', 'swiss')");
    await expect(run("INSERT INTO tournaments (id, event_id, slug, title, game, format) VALUES ('t2', 'e1', 'cup-two', 'Cup Two', 'bgmi', 'swiss')")).rejects.toThrow(); // one wrapper per event
    await expect(run("INSERT INTO tournaments (id, event_id, slug, title, game, format) VALUES ('t3', 'e2', 'cup-one', 'Cup Three', 'bgmi', 'swiss')")).rejects.toThrow(); // slug unique
    await expect(run("INSERT INTO tournaments (id, event_id, slug, title, game, format) VALUES ('t4', 'e2', 'cup-four', 'Cup Four', 'chess', 'swiss')")).rejects.toThrow(); // game enum
    await expect(run("INSERT INTO tournaments (id, event_id, slug, title, game, format, status) VALUES ('t5', 'e2', 'cup-five', 'Cup Five', 'bgmi', 'swiss', 'weird')")).rejects.toThrow();
    await expect(run("INSERT INTO tournaments (id, event_id, slug, title, game, format, starts_at, ends_at) VALUES ('t6', 'e2', 'cup-six', 'Cup Six', 'bgmi', 'swiss', 20, 10)")).rejects.toThrow(); // dates
    await expect(run("INSERT INTO tournaments (id, event_id, slug, title, game, format) VALUES ('t7', 'no-event', 'cup-seven', 'Cup Seven', 'bgmi', 'swiss')")).rejects.toThrow(); // FK to events

    await run("INSERT INTO player_profiles (user_id, slug, handle) VALUES (?1, 'alice-pro', 'Alice')", uid);
    await expect(run("INSERT INTO player_profiles (user_id, slug, handle, visibility) VALUES ('u-bob', 'alice-pro', 'Bob', 'private')")).rejects.toThrow(); // slug unique
    await expect(run("INSERT INTO player_profiles (user_id, slug, handle, visibility) VALUES ('u-bob', 'bob-pro', 'Bob', 'everyone')")).rejects.toThrow();
    expect(await one("SELECT COUNT(*) FROM player_profiles WHERE visibility = 'private'")).toBe(1); // private is the default
    await run("INSERT INTO player_games (user_id, game, in_game_name) VALUES (?1, 'bgmi', 'Al')", uid);
    await expect(run("INSERT INTO player_games (user_id, game, in_game_name) VALUES (?1, 'bgmi', 'Al2')", uid)).rejects.toThrow(); // one row per game

    await run("INSERT INTO team_profiles (id, owner_user_id, name, slug, updated_at) VALUES ('tp1', ?1, 'Wolves', 'wolves', 'x')", uid);
    const lft = (id: string, kind: string, team: string | null) => run("INSERT INTO lft_listings (id, kind, author_user_id, team_profile_id, game, message, expires_at) VALUES (?1, ?2, ?3, ?4, 'bgmi', 'hello there', ?5)", id, kind, uid, team, T);
    await lft("l1", "looking_for_team", null);
    await lft("l2", "looking_for_player", "tp1");
    await expect(lft("l3", "looking_for_player", null)).rejects.toThrow(); // a recruiting post must name its team
    await expect(lft("l4", "looking_for_team", "tp1")).rejects.toThrow(); // a player post must not
    await expect(run("INSERT INTO lft_listings (id, kind, author_user_id, game, message, expires_at, rank_min_ordinal, rank_max_ordinal) VALUES ('l5', 'looking_for_team', ?1, 'bgmi', 'hello there', ?2, 20, 10)", uid, T)).rejects.toThrow(); // rank range
    await expect(run("INSERT INTO lft_listings (id, kind, author_user_id, game, message, expires_at) VALUES ('l6', 'looking_for_team', ?1, 'bgmi', ?3, ?2)", uid, T, "x".repeat(601))).rejects.toThrow(); // 600 chars
    await run("INSERT INTO lft_applications (id, listing_id, applicant_user_id, contact) VALUES ('a1', 'l1', 'u-bob', 'bob#1')");
    await expect(run("INSERT INTO lft_applications (id, listing_id, applicant_user_id) VALUES ('a2', 'l1', 'u-bob')")).rejects.toThrow(); // one per person per listing
    await expect(run("INSERT INTO lft_applications (id, listing_id, applicant_user_id, status) VALUES ('a3', 'l1', 'u-carol', 'maybe')")).rejects.toThrow();
    await run("INSERT INTO lft_reports (id, listing_id, reporter, reason_code) VALUES ('r1', 'l1', 'h1', 'spam')");
    await expect(run("INSERT INTO lft_reports (id, listing_id, reporter, reason_code) VALUES ('r2', 'l1', 'h1', 'spam')")).rejects.toThrow(); // one reporter once

    const dsp = (id: string, status: string, resolvedAt: number | null) => run("INSERT INTO disputes (id, tournament_id, type, status, summary, due_at, resolved_at) VALUES (?1, 't1', 'other', ?2, 'x', ?3, ?4)", id, status, T, resolvedAt);
    await dsp("d1", "open", null);
    await expect(dsp("d2", "resolved", null)).rejects.toThrow(); // resolved without a time
    await expect(dsp("d3", "open", T)).rejects.toThrow(); // a time without being decided
    await dsp("d4", "rejected", T);
    await expect(run("INSERT INTO disputes (id, tournament_id, type, status, summary, due_at) VALUES ('d5', 't1', 'other', 'bogus', 'x', 1)")).rejects.toThrow();
    await expect(run("INSERT INTO disputes (id, tournament_id, type, status, summary, due_at, outcome) VALUES ('d6', 't1', 'other', 'open', 'x', 1, 'won')")).rejects.toThrow();
    const ev = (id: string, mime: string, size: number, sha: string) => run("INSERT INTO dispute_evidence (id, dispute_id, mime_type, size_bytes, sha256) VALUES (?1, 'd1', ?2, ?3, ?4)", id, mime, size, sha);
    await ev("v1", "image/png", 1000, "aa");
    await expect(ev("v2", "image/png", 1000, "aa")).rejects.toThrow(); // same screenshot twice in one dispute
    await expect(ev("v3", "image/gif", 1000, "bb")).rejects.toThrow();
    await expect(ev("v4", "image/png", 409_601, "cc")).rejects.toThrow(); // over 400 KB
    await expect(ev("v5", "image/png", 0, "dd")).rejects.toThrow();
    await ev("v6", "image/webp", 409_600, "ee"); // exactly 400 KB is allowed
    await run("INSERT INTO dispute_evidence_blobs (evidence_id, bytes) VALUES ('v1', x'89504e47')");

    await run("INSERT INTO dispute_events (id, dispute_id, actor_role, action) VALUES ('ev1', 'd1', 'team', 'comment')");
    await expect(run("UPDATE dispute_events SET action = 'x' WHERE id = 'ev1'")).rejects.toThrow(/append-only/);
    await run("INSERT INTO discord_outbox (id, kind, guild_id, idempotency_key) VALUES ('o1', 'ping_lobby', 'g1', 'k')");
    await expect(run("INSERT INTO discord_outbox (id, kind, guild_id, idempotency_key) VALUES ('o2', 'ping_lobby', 'g1', 'k')")).rejects.toThrow(); // a retry cannot enqueue twice
    await expect(run("INSERT INTO discord_outbox (id, kind, guild_id, idempotency_key) VALUES ('o3', 'rm_rf', 'g1', 'k3')")).rejects.toThrow();

    // cascades: deleting a dispute removes its evidence, blob and events; deleting an event removes its tournament and the disputes under it
    await run("DELETE FROM disputes WHERE id = 'd1'");
    expect(await one("SELECT COUNT(*) FROM dispute_evidence WHERE dispute_id = 'd1'")).toBe(0);
    expect(await one("SELECT COUNT(*) FROM dispute_evidence_blobs")).toBe(0);
    expect(await one("SELECT COUNT(*) FROM dispute_events")).toBe(0);
    await run("DELETE FROM events WHERE id = 'e1'");
    expect(await one("SELECT COUNT(*) FROM tournaments")).toBe(0);
    expect(await one("SELECT COUNT(*) FROM disputes")).toBe(0);
    await run("DELETE FROM users WHERE id = ?1", uid);
    expect(await one("SELECT COUNT(*) FROM player_profiles WHERE user_id = ?1", uid)).toBe(0);
    expect(await one("SELECT COUNT(*) FROM lft_listings WHERE author_user_id = ?1", uid)).toBe(0);
    expect(await one("SELECT COUNT(*) FROM lft_applications")).toBe(0); // applications to the deleted listings went too
    expect(await foreignKeyViolations()).toEqual([]);
  });

  it("0053 (Discord stage) is idempotent, refuses duplicate links and bad settings, and cascades with the registration", async () => {
    const m = (env.TEST_MIGRATIONS as D1Migration[]).find((x) => x.name.startsWith("0053"))!;
    expect(m.queries.length).toBeGreaterThan(4);
    for (const q of m.queries) await env.DB.prepare(q).run(); // second run: nothing changes, nothing throws
    for (const t of ["v3_registration_discord", "discord_link_codes", "v3_discord_settings"]) expect(await one("SELECT COUNT(*) FROM sqlite_master WHERE name = ?1", t)).toBe(1);
    await run("INSERT INTO users (id, email, name, pw_hash, pw_salt, pw_iter, created_at, discord_user_id) VALUES ('d1', 'd1@example.com', 'D1', 'x', 'x', 1, 'x', '111111111111111111')");
    await expect(run("INSERT INTO users (id, email, name, pw_hash, pw_salt, pw_iter, created_at, discord_user_id) VALUES ('d2', 'd2@example.com', 'D2', 'x', 'x', 1, 'x', '111111111111111111')")).rejects.toThrow(); // one Discord account, one user
    await run("INSERT INTO users (id, email, name, pw_hash, pw_salt, pw_iter, created_at) VALUES ('d3', 'd3@example.com', 'D3', 'x', 'x', 1, 'x')");
    await run("INSERT INTO users (id, email, name, pw_hash, pw_salt, pw_iter, created_at) VALUES ('d4', 'd4@example.com', 'D4', 'x', 'x', 1, 'x')"); // many users without a link are fine
    await run("INSERT INTO discord_link_codes (user_id, code_hash, expires_at) VALUES ('d3', 'h1', 5)");
    await expect(run("INSERT INTO discord_link_codes (user_id, code_hash, expires_at) VALUES ('d4', 'h1', 5)")).rejects.toThrow(); // a code hash is unique
    await expect(run("INSERT INTO v3_discord_settings (tournament_id, archive_mode) VALUES ('nope', 'readonly')")).rejects.toThrow(); // FK to tournaments
    await run("DELETE FROM users WHERE id = 'd3'");
    expect(await one("SELECT COUNT(*) FROM discord_link_codes WHERE user_id = 'd3'")).toBe(0); // deleted with the account
    expect(await foreignKeyViolations()).toEqual([]);
  });
});
